// app/sitemap.xml/route.js

import { getAllValidPaths } from "@/lib/seo-utils";
import { DOCTOR } from "@/data/seo-data";

export async function GET() {
  const paths = getAllValidPaths();
  const now = new Date().toISOString();

  const urls = [
    ...paths.map(({ location, problem, intent }) => {
      const url = `${DOCTOR.domain}/${location}/${problem}/`;

      const changeFrequency = intent
        ? {
            treatment: "weekly",
            cost: "weekly",
            "best-doctor": "monthly",
            symptoms: "monthly",
            surgery: "monthly",
            "hearing-aids": "monthly",
          }[intent] ?? "monthly"
        : "monthly";

      const priority =
        !intent ? 0.6 :
        changeFrequency === "weekly" ? 0.9 :
        0.7;

      return `
        <url>
          <loc>${url}</loc>
          <lastmod>${now}</lastmod>
          <changefreq>${changeFrequency}</changefreq>
          <priority>${priority}</priority>
        </url>
      `;
    }),
  ].join("");

  const xml = `<?xml version="1.0" encoding="UTF-8"?>
  <urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
    ${urls}
  </urlset>`;

  return new Response(xml, {
    headers: {
      "Content-Type": "application/xml",
    },
  });
}